/** @param {NS} ns */
export async function main(ns) {
  const servers = [];
  const visited = new Set();
  const queue = ['home'];

  // BFS scan all reachable servers
  while (queue.length > 0) {
    const server = queue.shift();
    if (visited.has(server)) continue;
    visited.add(server);
    servers.push(server);

    const neighbors = ns.scan(server);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) queue.push(neighbor);
    }
  }

  // Attempt to nuke all servers
  for (const server of servers) {
    const ports = ns.getServerNumPortsRequired(server);
    if (ports <= 0 && !ns.hasRootAccess(server)) {
      ns.nuke(server);
    }
  }

  // Find best hackable server
  let target = null;
  let bestRatio = 0;
  const hackLevel = ns.getHackingLevel();

  for (const server of servers) {
    if (server === 'home') continue;
    const reqLevel = ns.getServerRequiredHackingLevel(server);
    if (reqLevel > hackLevel) continue;
    if (!ns.hasRootAccess(server)) continue;

    const maxMoney = ns.getServerMaxMoney(server);
    if (maxMoney <= 0) continue;

    const ratio = maxMoney / (reqLevel + 1);
    if (ratio > bestRatio) {
      bestRatio = ratio;
      target = server;
    }
  }

  if (!target) {
    ns.tprint('No hackable target found');
    return;
  }

  ns.tprint(`Target: ${target}`);

  // Hack loop
  while (true) {
    const security = ns.getServerSecurityLevel(target);
    const minSecurity = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);

    if (security > minSecurity + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

